CREATE TABLE IF NOT EXISTS rural_insurance_product_versions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organization_id UUID,name TEXT NOT NULL,version TEXT NOT NULL,coverage JSONB NOT NULL,rate_percent NUMERIC(9,4) NOT NULL,valid_from DATE NOT NULL,valid_to DATE,status TEXT NOT NULL CHECK(status IN('draft','active','retired')),created_by UUID REFERENCES users(id),UNIQUE(organization_id,name,version));
CREATE TABLE IF NOT EXISTS rural_insurance_quotes(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organization_id UUID NOT NULL,product_version_id UUID NOT NULL REFERENCES rural_insurance_product_versions(id),farmer_id UUID,order_id UUID,asset_id UUID,subsidy_application_id UUID,sum_insured NUMERIC(18,2) NOT NULL,base_premium NUMERIC(18,2) NOT NULL,subsidy_amount NUMERIC(18,2) NOT NULL,farmer_payable NUMERIC(18,2) NOT NULL,input_evidence JSONB NOT NULL,status TEXT NOT NULL,decision_notes TEXT,created_by UUID REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS rural_insurance_policies(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organization_id UUID NOT NULL,quote_id UUID NOT NULL REFERENCES rural_insurance_quotes(id),policy_number TEXT UNIQUE NOT NULL,status TEXT NOT NULL,starts_on DATE NOT NULL,ends_on DATE NOT NULL,endorsements JSONB NOT NULL DEFAULT'[]',premium_schedule JSONB NOT NULL DEFAULT'[]',finance_reference JSONB NOT NULL DEFAULT'{}',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS rural_insurance_claims(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),policy_id UUID NOT NULL REFERENCES rural_insurance_policies(id),organization_id UUID NOT NULL,loss_date DATE NOT NULL,loss_type TEXT NOT NULL,claim_amount NUMERIC(18,2) NOT NULL,description TEXT,status TEXT NOT NULL,decision_notes TEXT,evidence JSONB NOT NULL DEFAULT'[]',survey JSONB,fraud_review JSONB,settlement JSONB,grievance JSONB,reported_by UUID REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS rural_insurance_audit(id BIGSERIAL PRIMARY KEY,aggregate_type TEXT NOT NULL,aggregate_id UUID NOT NULL,event_type TEXT NOT NULL,actor_id UUID REFERENCES users(id),payload JSONB NOT NULL DEFAULT'{}',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE OR REPLACE FUNCTION rural_insurance_audit_immutable() RETURNS TRIGGER AS $$ BEGIN RAISE EXCEPTION 'insurance audit is append-only'; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS trg_rural_insurance_audit_immutable ON rural_insurance_audit; CREATE TRIGGER trg_rural_insurance_audit_immutable BEFORE UPDATE OR DELETE ON rural_insurance_audit FOR EACH ROW EXECUTE FUNCTION rural_insurance_audit_immutable();
